`timescale 1ns/1ps

// STM32 Mode31/Menu compatible user interface for the PL controller.
//
// key_click and key_long are one-clock pulses generated by key_events.v.
// The normal page uses K1 to start/stop, K2/K3 to move the location target,
// and K4 to select angle-gain, location-gain, or menu pages.  On either gain
// page RP1/RP2/RP3 take over Kp/Ki/Kd only after their physical positions have
// first been brought close to the stored values, as in Mode31.c.  RP4 is used
// as an optional position-target knob on the location page; K2/K3 remain
// available for the same fixed 408-count steps as the STM32 application.
module pendulum_ui #(
    parameter integer ADC_SPAN_COUNTS = 3974,
    parameter integer DEFAULT_CENTER_ANGLE = 2050,
    parameter integer DEFAULT_START_PWM = 35,
    parameter integer DEFAULT_START_TIME_MS = 90,
    parameter integer DEFAULT_PWM_OFFSET = 0,
    parameter integer USE_RP4_TARGET = 1
) (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        sample_tick_1ms,
    input  wire        capture_reset,
    input  wire [3:0]  key_click,
    input  wire [3:0]  key_long,
    input  wire [11:0] rp1_adc,
    input  wire [11:0] rp2_adc,
    input  wire [11:0] rp3_adc,
    input  wire [11:0] rp4_adc,
    output reg         run_request,
    output reg  [1:0]  page,
    output reg signed [31:0] location_target,
    output reg  [15:0] angle_kp_q8,
    output reg  [15:0] angle_ki_q8,
    output reg  [15:0] angle_kd_q8,
    output reg  [15:0] location_kp_q8,
    output reg  [15:0] location_ki_q8,
    output reg  [15:0] location_kd_q8,
    output reg  [11:0] center_angle,
    output reg  [7:0]  start_pwm,
    output reg  [15:0] start_time_ms,
    output reg  [7:0]  pwm_offset,
    output reg  [1:0]  menu_index,
    output reg         menu_edit,
    output reg         save_pulse,
    output reg         angle_kp_armed,
    output reg         angle_ki_armed,
    output reg         angle_kd_armed,
    output reg         location_kp_armed,
    output reg         location_ki_armed,
    output reg         location_kd_armed,
    output reg         location_target_armed
);
    localparam [1:0] PAGE_RUN      = 2'd0;
    localparam [1:0] PAGE_ANGLE    = 2'd1;
    localparam [1:0] PAGE_LOCATION = 2'd2;
    localparam [1:0] PAGE_MENU     = 2'd3;

    // Q8.8 maxima are the same engineering ranges as STM32 Mode31.c:
    // angle (Kp/Ki/Kd) = (1, 0.5, 1), location = (5, 1, 10).  Each mapping
    // is a constant multiply by a precomputed Q24 reciprocal so the divider
    // is a single DSP48 + shift instead of a large variable-divider chain.
    localparam [63:0] SPAN64 = ADC_SPAN_COUNTS;
    localparam [63:0] RECIP64_256  = ((64'd1 << 24) * 64'd256  + SPAN64 - 64'd1) / SPAN64;
    localparam [63:0] RECIP64_128  = ((64'd1 << 24) * 64'd128  + SPAN64 - 64'd1) / SPAN64;
    localparam [63:0] RECIP64_1280 = ((64'd1 << 24) * 64'd1280 + SPAN64 - 64'd1) / SPAN64;
    localparam [63:0] RECIP64_2560 = ((64'd1 << 24) * 64'd2560 + SPAN64 - 64'd1) / SPAN64;
    localparam [23:0] RECIP_Q24_256  = RECIP64_256[23:0];
    localparam [23:0] RECIP_Q24_128  = RECIP64_128[23:0];
    localparam [23:0] RECIP_Q24_1280 = RECIP64_1280[23:0];
    localparam [23:0] RECIP_Q24_2560 = RECIP64_2560[23:0];

    wire [11:0] rp1_clipped = (rp1_adc > ADC_SPAN_COUNTS) ? ADC_SPAN_COUNTS[11:0] : rp1_adc;
    wire [11:0] rp2_clipped = (rp2_adc > ADC_SPAN_COUNTS) ? ADC_SPAN_COUNTS[11:0] : rp2_adc;
    wire [11:0] rp3_clipped = (rp3_adc > ADC_SPAN_COUNTS) ? ADC_SPAN_COUNTS[11:0] : rp3_adc;

    wire [35:0] rp_angle_kp_p = rp1_clipped * RECIP_Q24_256;
    wire [35:0] rp_angle_ki_p = rp2_clipped * RECIP_Q24_128;
    wire [35:0] rp_angle_kd_p = rp3_clipped * RECIP_Q24_256;
    wire [35:0] rp_location_kp_p = rp1_clipped * RECIP_Q24_1280;
    wire [35:0] rp_location_ki_p = rp2_clipped * RECIP_Q24_256;
    wire [35:0] rp_location_kd_p = rp3_clipped * RECIP_Q24_2560;

    wire [15:0] rp_angle_kp = rp_angle_kp_p >> 24;
    wire [15:0] rp_angle_ki = rp_angle_ki_p >> 24;
    wire [15:0] rp_angle_kd = rp_angle_kd_p >> 24;
    wire [15:0] rp_location_kp = rp_location_kp_p >> 24;
    wire [15:0] rp_location_ki = rp_location_ki_p >> 24;
    wire [15:0] rp_location_kd = rp_location_kd_p >> 24;
    wire signed [31:0] rp_location_target =
        ($signed({1'b0, rp4_adc}) * 32'sd17998) / ADC_SPAN_COUNTS - 32'sd8999;

    function integer abs_i;
        input integer value;
        begin
            abs_i = (value < 0) ? -value : value;
        end
    endfunction

    task automatic clear_takeover;
        begin
            angle_kp_armed <= 1'b0;
            angle_ki_armed <= 1'b0;
            angle_kd_armed <= 1'b0;
            location_kp_armed <= 1'b0;
            location_ki_armed <= 1'b0;
            location_kd_armed <= 1'b0;
        end
    endtask

    integer gain_diff;
    integer signed_diff;
    always @(posedge clk) begin
        if (!rst_n) begin
            run_request <= 1'b0;
            page <= PAGE_RUN;
            location_target <= 32'sd0;
            angle_kp_q8 <= 16'd64;       // 0.25
            angle_ki_q8 <= 16'd2;        // 0.0078, nearest Q8.8 to 0.009
            angle_kd_q8 <= 16'd105;      // 0.41
            location_kp_q8 <= 16'd133;   // 0.52
            location_ki_q8 <= 16'd3;     // 0.0117, nearest Q8.8 to 0.01
            location_kd_q8 <= 16'd1167;  // 4.56
            center_angle <= DEFAULT_CENTER_ANGLE[11:0];
            start_pwm <= DEFAULT_START_PWM[7:0];
            start_time_ms <= DEFAULT_START_TIME_MS[15:0];
            pwm_offset <= DEFAULT_PWM_OFFSET[7:0];
            menu_index <= 2'd0;
            menu_edit <= 1'b0;
            save_pulse <= 1'b0;
            angle_kp_armed <= 1'b0;
            angle_ki_armed <= 1'b0;
            angle_kd_armed <= 1'b0;
            location_kp_armed <= 1'b0;
            location_ki_armed <= 1'b0;
            location_kd_armed <= 1'b0;
            location_target_armed <= 1'b0;
        end else begin
            save_pulse <= 1'b0;

            // K4 long press is the STM32 save action.  FPGA builds can use
            // save_pulse to update a BRAM/flash-backed parameter store.
            if (key_long[3])
                save_pulse <= 1'b1;

            if (page == PAGE_MENU) begin
                // Menu.c: K1=up/decrease, K2=down/increase, K3=enter,
                // K4=back.  Values are clamped to the STM32 limits.
                if (key_click[0]) begin
                    if (menu_edit) begin
                        case (menu_index)
                            2'd0: if (center_angle > 1900) center_angle <= center_angle - 10;
                            2'd1: if (start_pwm > 0) start_pwm <= start_pwm - 1'b1;
                            2'd2: if (start_time_ms > 0) start_time_ms <= start_time_ms - 1'b1;
                            default: if (pwm_offset > 0) pwm_offset <= pwm_offset - 1'b1;
                        endcase
                    end else if (menu_index == 0) begin
                        menu_index <= 2'd3;
                    end else begin
                        menu_index <= menu_index - 1'b1;
                    end
                end
                if (key_click[1]) begin
                    if (menu_edit) begin
                        case (menu_index)
                            2'd0: if (center_angle < 2200) center_angle <= center_angle + 10;
                            2'd1: if (start_pwm < 100) start_pwm <= start_pwm + 1'b1;
                            2'd2: if (start_time_ms < 200) start_time_ms <= start_time_ms + 1'b1;
                            default: if (pwm_offset < 50) pwm_offset <= pwm_offset + 1'b1;
                        endcase
                    end else if (menu_index == 3) begin
                        menu_index <= 2'd0;
                    end else begin
                        menu_index <= menu_index + 1'b1;
                    end
                end
                if (key_click[2])
                    menu_edit <= ~menu_edit;
                if (key_click[3]) begin
                    menu_edit <= 1'b0;
                    page <= PAGE_RUN;
                    clear_takeover();
                    location_target_armed <= 1'b0;
                end
            end else begin
                // K1/K2/K3 retain Mode31 behavior on both gain pages.
                if (key_click[0])
                    run_request <= ~run_request;
                if (key_click[1]) begin
                    if (location_target < 8999 - 408)
                        location_target <= location_target + 408;
                    else
                        location_target <= 32'sd8999;
                end
                if (key_click[2]) begin
                    if (location_target > -8999 + 408)
                        location_target <= location_target - 408;
                    else
                        location_target <= -32'sd8999;
                end
                if (key_click[3]) begin
                    clear_takeover();
                    location_target_armed <= 1'b0;
                    if (page == PAGE_RUN) begin
                        page <= PAGE_ANGLE;
                    end else if (page == PAGE_ANGLE) begin
                        page <= PAGE_LOCATION;
                    end else begin
                        page <= PAGE_MENU;
                        menu_index <= 2'd0;
                        menu_edit <= 1'b0;
                    end
                end
            end

            // ADC gain hand-over is sampled at 1 kHz.  The first movement
            // after entering a page must pass through the STM32-style window.
            if (sample_tick_1ms) begin
                if (page == PAGE_ANGLE) begin
                    signed_diff = $signed({1'b0, rp_angle_kp}) - $signed({1'b0, angle_kp_q8});
                    if (!angle_kp_armed && abs_i(signed_diff) <= 8)
                        angle_kp_armed <= 1'b1;
                    signed_diff = $signed({1'b0, rp_angle_ki}) - $signed({1'b0, angle_ki_q8});
                    if (!angle_ki_armed && abs_i(signed_diff) <= 1)
                        angle_ki_armed <= 1'b1;
                    signed_diff = $signed({1'b0, rp_angle_kd}) - $signed({1'b0, angle_kd_q8});
                    if (!angle_kd_armed && abs_i(signed_diff) <= 8)
                        angle_kd_armed <= 1'b1;
                    if (angle_kp_armed) angle_kp_q8 <= rp_angle_kp;
                    if (angle_ki_armed) angle_ki_q8 <= rp_angle_ki;
                    if (angle_kd_armed) angle_kd_q8 <= rp_angle_kd;
                end else if (page == PAGE_LOCATION) begin
                    signed_diff = $signed({1'b0, rp_location_kp}) - $signed({1'b0, location_kp_q8});
                    if (!location_kp_armed && abs_i(signed_diff) <= 8)
                        location_kp_armed <= 1'b1;
                    signed_diff = $signed({1'b0, rp_location_ki}) - $signed({1'b0, location_ki_q8});
                    if (!location_ki_armed && abs_i(signed_diff) <= 1)
                        location_ki_armed <= 1'b1;
                    signed_diff = $signed({1'b0, rp_location_kd}) - $signed({1'b0, location_kd_q8});
                    if (!location_kd_armed && abs_i(signed_diff) <= 8)
                        location_kd_armed <= 1'b1;
                    signed_diff = rp_location_target - location_target;
                    if ((USE_RP4_TARGET != 0) && !location_target_armed &&
                        abs_i(signed_diff) <= 256)
                        location_target_armed <= 1'b1;
                    if (location_kp_armed) location_kp_q8 <= rp_location_kp;
                    if (location_ki_armed) location_ki_q8 <= rp_location_ki;
                    if (location_kd_armed) location_kd_q8 <= rp_location_kd;
                    if ((USE_RP4_TARGET != 0) && location_target_armed)
                        location_target <= rp_location_target;
                end
            end

            // Mode31.c clears LocationPID.Target when the swing-up captures
            // the pendulum upright, so the outer loop balances in place at
            // the captured encoder position.
            if (capture_reset) begin
                location_target <= 32'sd0;
                location_target_armed <= 1'b0;
            end
        end
    end
endmodule
